# TEST ONLY: P2D launch (rig02, RES 480, frames): N1 (the watch check held: saber LIT/OFF, flare, flashlight), H1, H2, D3 (DG fix).
import sys; sys.path.insert(0, '.')
from lib import S
s = S()
REST_R = (0.25, 1.30, -0.30); REST_L = (-0.25, 1.30, -0.30)
s.add('wait 20', 'vr_control_scheme 0', 'bd_tips 0', 'crosshair 0', 'screenblocks 10', 'buddha', 'set ssq_debug 1', 'set ubqs_diag 0',
      'set rsqdg_debug 1', 'set rsqdg_trace 1', 'set rsqgc_debug_log 1', 'set rsqff_debug 1', 'set rsqgc_watch 1', 'qz_hmd "0 1.6 0 0 0 0"')
s.r(*REST_R); s.l(*REST_L); s.w(20); s.add('netevent p2_clearmon', 'give SSQ_ShieldSaw'); s.w(5); s.add('netevent rsqgb_dbg_all'); s.w(40)
s.add('use UBQS_Saber'); s.w(60); s.add('netevent p2_off 0', 'netevent p2_lit 0')
# ---- N1: the watch check, the back of the wrist turned to the face and held still (Accessibility's reader: roll >= 35 that way)
s.add('qz_hmd "0 1.6 0 -25 0 0"')
s.add('echo N1_SABER_LIT'); s.r(0.0, 1.45, -0.30, 0, 0, -60); s.w(50); s.add('netevent p2_lit 10')
s.add('echo N1_SABER_OFF', 'netevent ubqs_ignite'); s.w(45); s.add('netevent p2_lit 11')
s.add('echo N1_SABER_WATCH2', 'set rsqgc_watch 2'); s.w(30); s.add('set rsqgc_watch 1', 'netevent ubqs_ignite'); s.w(10); s.add('netevent p2_lit 12', 'echo N1_SABER_END'); s.r(*REST_R); s.w(20)
s.add('echo N1_FLARE', 'give RSQFF_Ammo 4', 'netevent rsqff_take'); s.w(40); s.add('netevent p2_ff 1')
s.l(0.0, 1.45, -0.30, 0, 0, 60); s.w(50); s.add('netevent p2_ff 2', 'echo N1_FLARE_WATCH2', 'set rsqgc_watch 2'); s.w(30); s.add('set rsqgc_watch 1', 'echo N1_FLARE_END'); s.l(*REST_L); s.w(10)
s.add('netevent rsqff_back'); s.w(30)
s.add('echo N1_TORCH', 'netevent rsqff_fl_take'); s.w(40); s.add('netevent p2_ff 3')
s.l(0.0, 1.45, -0.30, 0, 0, 60); s.w(50); s.add('netevent p2_ff 4', 'echo N1_TORCH_WATCH2', 'set rsqgc_watch 2'); s.w(30); s.add('set rsqgc_watch 1', 'echo N1_TORCH_END'); s.l(*REST_L); s.w(10)
s.add('netevent rsqff_fl_back'); s.w(30); s.add('netevent p2_ff 5', 'qz_hmd "0 1.6 0 0 0 0"')
# ---- H1 ricochet with two rings painted. ShieldSaw aim (rig): its forward = qz pitch - 30, qz yaw (+ left).
s.add('echo H1', 'netevent p2_tp -320 0 0', 'netevent p2_ssqset 1'); s.w(60); s.add('netevent p2_off 20', 'netevent p2_ssq 0')
s.add('netevent p2_xyit:DoomImp -60 150 1', 'netevent p2_xyit:DoomImp -40 -150 1'); s.w(30); s.add('netevent p2_items')
s.l(-0.25, 1.20, -0.35, 28, 29, 0); s.w(4); s.add('echo H1_PAINT', 'qz_ltrigger 1'); s.w(12); s.add('netevent p2_ssq 1')
s.l(-0.25, 1.20, -0.35, 28, -30, 0); s.w(12); s.add('netevent p2_ssq 2'); s.l(-0.25, 1.20, -0.35, 28, 0, 0); s.w(4); s.add('netevent p2_ssq 3', 'set rsqa_onehand 1'); s.w(2)
s.add('echo H1_THROW', 'netevent p2_move 0 -60 330', 'netevent p2_xyit:DoomImp -200 100 1', 'netevent rsqa_alt 6 1'); s.w(1); s.add('netevent rsqa_alt 6 0', 'qz_ltrigger 0', 'set rsqa_onehand 0')
s.w(80); s.add('echo H1_A_BACK_IN_VIEW', 'netevent p2_move 0 -60 150'); s.w(80); s.add('netevent p2_ssq 4', 'netevent p2_items', 'echo H1_END'); s.w(160)
s.add('netevent p2_ssqset 1'); s.w(100); s.add('netevent p2_ssqset 1'); s.w(40); s.add('netevent p2_ssq 5')
# ---- H2 a zombieman's hitscan on the plate (plate facing forward: off hand yaw -90), muzzle block off
s.add('echo H2', 'netevent p2_clearmon', 'netevent p2_tp -320 0 0', 'set ssq_hitscan_guard 0'); s.l(-0.05, 1.15, -0.30, 0, -90, 0); s.w(20); s.add('netevent p2_ssq 10')
s.add('netevent p2_zm 400 0'); s.w(10)
s.add('echo H2_FAR_NOPUFF', 'netevent p2_hp 100', 'netevent p2_zshoot 1'); s.w(10)
s.add('echo H2_FAR_PUFF', 'netevent p2_hp 100', 'netevent p2_zshoot 0'); s.w(10)
s.add('echo H2_FAR_MUZZLE_ON', 'set ssq_hitscan_guard 1', 'netevent p2_hp 100'); s.w(3); s.add('netevent p2_zshoot 1'); s.w(10)
s.add('set ssq_hitscan_guard 0', 'netevent p2_zclear', 'netevent p2_zm 50 0'); s.w(10)
s.add('echo H2_NEAR_NOPUFF', 'netevent p2_hp 100', 'netevent p2_zshoot 1'); s.w(10)
s.add('netevent p2_zclear', 'set ssq_hitscan_guard 1'); s.l(*REST_L); s.w(5); s.add('netevent p2_ssqset 0'); s.w(30)
# ---- D3 a full gun you carry, pulled (Distance Grab rebuilt with the fix)
s.add('echo D3', 'netevent p2_clearfloor', 'netevent p2_tp -320 0 0', 'give Shot_Gun'); s.w(2); s.add('use Shot_Gun', 'give ammo'); s.w(90)
s.add('netevent p2_off 30', 'netevent p2_vani:Shot_Gun 160 0'); s.w(5); s.add('netevent p2_items')
s.r(0.25, 1.30, -0.30, -11, -30, 90); s.w(30)
s.r(0.25, 1.30, -0.30, 2, -30, 90); s.w(2); s.r(0.25, 1.30, -0.30, 15, -30, 90); s.w(2); s.r(0.25, 1.30, -0.30, 15, -30, 0); s.w(4)
s.add('echo D3_CATCH', 'qz_hmd "0 1.6 0 -40 0 0"'); s.r(0.25, 1.30, -0.30, -11, -30, 90); s.w(60); s.add('netevent p2_items', 'netevent p2_inv', 'echo D3_END'); s.w(20)
s.add('echo P2D_END'); s.w(5); s.add('quit')
open(sys.argv[1], 'w').write(s.text())
print(len(s.c), 'commands')
